MEMBER_DISCOUNT = 0.05
COUPONS = {
    'SAVE10': lambda t: t * 0.9,
    'FLAT50': lambda t: max(0.0, t - 50),
}

def order_total(qty, unit_price, coupon, member):
    if qty <= 0:
        return 'invalid'
    total = qty * unit_price
    total = COUPONS.get(coupon, lambda t: t)(total)
    if member:
        total *= 1 - MEMBER_DISCOUNT
    return f'{total:.2f}'

q, pr, c, m = input().split()
